    background-color: #e6e6e6; /* 中浅灰表头 */
    color: #000000;
}
/* 表格斑马条纹效果 */
#wenyan table tr:nth-child(2n) {
    background-color: #f7f7f7; /* 极浅灰间隔 */
}
/* 引用块 */
#wenyan blockquote {
    background: #f9f9f9;
    border-left: 4px solid #000000; /* 纯黑强调边框 */
    margin: 1.5em 0;
    padding: 1em 1em 1em 2em;
    color: #555555;
    font-size: 0.95em;
    position: relative;
}
/* 引用块前缀：背景大引号点缀 */
#wenyan blockquote::before {
    content: "“";
    font-size: 3em;
    font-family: serif;
    color: #dddddd;
    position: absolute;
    left: 10px;
    top: -10px;
}
/* 引用块后缀 */
#wenyan blockquote::after {
}
/* 行内代码 */
#wenyan p code {
    color: #000000;
    background-color: #f0f0f0; /* 浅灰底色 */
    padding: 3px 6px;
    font-size: 0.88em;
    border-radius: 3px;
    border: 1px solid #e0e0e0;
}
/* 代码块外围 */
#wenyan pre {
    border-radius: 6px;
    line-height: 1.6;
    margin: 1.5em 0;
    padding: 1em;
    background-color: #1a1a1a; /* 与内部代码块统一的深灰/近黑色 */
    box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.8);
}
/* 代码块 */
#wenyan pre code {
    display: block;
    overflow-x: auto;
    margin: 0;
    padding: 0;
    color: #e5e5e5; /* 浅灰色代码文字 */
    background-color: #1a1a1a; /* 保持一致的深灰/近黑色 */
}
/* 分割线 */
#wenyan hr {
    border: none;
    border-top: 1px solid #999999;
    margin-top: 2.5em;
    margin-bottom: 2.5em;
    position: relative;
}
/* 分割线中心菱形装饰 */
#wenyan hr::before {
    content: "◆";
    position: absolute;
    top: -0.8em;
    left: 50%;
    transform: translateX(-50%);
    color: #999999;
    background-color: #ffffff;
    padding: 0 10px;
}
/* 链接 */
#wenyan a {
    word-wrap: break-word;
    color: #000000;
    font-weight: bold;
    text-decoration: none;
    border-bottom: 1px solid #000000; /* 使用下划线来突出黑白主题的链接 */
}
/* 原始链接旁脚注上标 */
#wenyan .footnote {
    color: #555555;
    font-size: 0.8em;
}
/* 脚注行 */
#wenyan #footnotes p {
    display: flex;
    margin: 0 0 0.5em 0;
    font-size: 0.88em;
    color: #666666;
}
/* 脚注行内编号 */
#wenyan .footnote-num {
    display: inline;
    width: 10%;
    font-weight: bold;
    color: #333333;
}
/* 脚注行内文字 */
#wenyan .footnote-txt {
    display: inline;
    width: 90%;
    word-wrap: break-word;
    word-break: break-all;
}
/* 多级列表样式：浏览器默认只有三级，第四级需手动指定 */
#wenyan ul { list-style-type: disc; }
#wenyan ul ul { list-style-type: circle; }
#wenyan ul ul ul { list-style-type: square; }
#wenyan ul ul ul ul { list-style-type: '□ '; }
#wenyan ul ul ul ul ul { list-style-type: disc; }

fireworks:
/**
 * * 主题名称：多彩烟花爆炸主题 (Colorful Fireworks Burst)
 * * 风格描述：深邃夜空底色，霓虹烟火点缀。全面采用 SVG 元素绘制正在爆炸、扩散的烟花效果，自带流畅动画，充满庆典与生机感。
 */

/* 全局属性 */
#wenyan {
    line-height: 1.8;
    font-size: 17px;
    color: #e0e6ed; /* 浅灰色文字，适合深色背景 */

    /* ================= 新增：夜空烟花爆炸背景 ================= */
    background-color: #0b0f19; /* 深邃夜空黑蓝色 */

    /* 背景使用 SVG 动画绘制：
       1. 随机分布的微小星星
       2. 一个大范围、正在扩散并变淡的烟花爆炸粒子群（通过 animate 元素控制）
    */
    background-image: url("data:image/svg+xml,%3Csvg width='200' height='200' xmlns='http://www.w3.org/2000/svg'%3E%3C!-- 静态微星 --%3E%3Ccircle cx='20' cy='30' r='0.5' fill='%23fff' opacity='0.3'/%3E%3Ccircle cx='150' cy='160' r='0.8' fill='%23fff' opacity='0.2'/%3E%3C!-- 动态爆炸粒子群 (中心在 100,100) --%3E%3Ccircle cx='100' cy='100' r='1' fill='%23FF4081' opacity='0'%3E%3Canimate attributeName='r' from='1' to='80' dur='4s' repeatCount='indefinite' /%3E%3Canimate attributeName='opacity' values='0;0.1;0' keyTimes='0;0.2;1' dur='4s' repeatCount='indefinite' /%3E%3C/circle%3E%3Ccircle cx='100' cy='100' r='1' fill='%2300E5FF' opacity='0'%3E%3Canimate attributeName='r' from='1' to='100' dur='4s' begin='1s' repeatCount='indefinite' /%3E%3Canimate attributeName='opacity' values='0;0.08;0' keyTimes='0;0.3;1' dur='4s' repeatCount='indefinite' /%3E%3C/circle%3E%3Ccircle cx='100' cy='100' r='1' fill='%23FFEB3B' opacity='0'%3E%3Canimate attributeName='r' from='1' to='60' dur='4s' begin='2s' repeatCount='indefinite' /%3E%3Canimate attributeName='opacity' values='0;0.12;0' keyTimes='0;0.1;1' dur='4s' repeatCount='indefinite' /%3E%3C/circle%3E%3C/svg%3E");

    /* 背景平铺并固定 */
    background-repeat: repeat;
    background-attachment: fixed;
    background-position: center top;

    /* 增加内边距 */
    padding: 20px;
    box-sizing: border-box;
}

/* 全局子元素属性 */
#wenyan h1,
#wenyan h2,
#wenyan h3,
#wenyan h4,
#wenyan h5,
#wenyan h6,
#wenyan p,
#wenyan pre {
    margin: 1.2em 0;
}

/* 段落 */
#wenyan p {
    letter-spacing: 0.5px;
}

/* 加粗 */
#wenyan p strong {
    color: #ff80ab; /* 霓虹粉 */
    font-weight: bold;
}

/* 斜体 */
#wenyan p em {
    color: #81d4fa; /* 霓虹蓝 */
    font-style: italic;
}

/* 一级标题：中央巨大爆炸绽放 */
#wenyan h1 {
    display: block; /* 必须为 block */
    text-align: center;
    font-size: 1.67em;
    color: #fff;
    margin-top: 2em;
    margin-bottom: 1.5em;
    position: relative;
    padding: 10px 0;
}

/* 一级标题文字 */
#wenyan h1 span {
    display: inline-block;
    padding: 0 15px;
    position: relative;
    z-index: 1;
    text-shadow: 0 0 10px rgba(255, 64, 129, 0.7); /* 霓虹发光 */
}

/* 一级标题后缀：居中、旋转的多彩烟花 */
#wenyan h1::after {
    /* 正确模式：content: url() + inline-block */
    /* 内部 SVG 包含 animateTransform 用于旋转，以及 animate 用于多彩 fill 变换 */
    content: url("data:image/svg+xml,%3Csvg width='30' height='30' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cg transform='rotate(0 12 12)'%3E%3CanimateTransform attributeName='transform' type='rotate' from='0 12 12' to='360 12 12' dur='5s' repeatCount='indefinite'/%3E%3Cpath d='M12 2v4M12 18v4M4.22 4.22l2.83 2.83M16.95 16.95l2.83 2.83M2 12h4M18 12h4M4.22 19.78l2.83-2.83M16.95 7.05l2.83-2.83' stroke='%23FF4081' stroke-width='2' stroke-linecap='round'%3E%3Canimate attributeName='stroke' values='%23FF4081;%2300E5FF;%23FFEB3B;%23FF4081' dur='3s' repeatCount='indefinite' /%3E%3C/path%3E%3C/g%3E%3C/svg%3E");
    display: block;
    text-align: center;
    margin-top: 8px;
    opacity: 0.8;
}

/* ================= 修改：二级标题爆炸效果 ================= */
#wenyan h2 {
    display: block; /* 必须为 block */
    text-align: left;
    font-size: 1.37em;
    color: #fff;
    font-weight: bold;
    padding: 8px 15px;
    margin-top: 1.8em;
    position: relative;

    /* 霓虹发光边框 */
    border: 2px solid #00e5ff;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0, 229, 255, 0.5);
}

/* 二级标题前缀：动态爆炸的烟花小图标 */
#wenyan h2::before {
    /* 内部 SVG：
       1. 中心点
       2. 向四周爆炸扩散的线条（通过 animate attributeName='d' 或渐变 stroke-dashoffset 实现扩散感）
    */
    content: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='12' cy='12' r='1.5' fill='%23FFEB3B'/%3E%3Cpath d='M12 12l0-8 M12 12l5.66 5.66 M12 12l-5.66 5.66 M12 12l8 0 M12 12l-8 0' stroke='%23FFEB3B' stroke-width='1.5' stroke-linecap='round' stroke-dasharray='0 20'%3E%3Canimate attributeName='stroke-dasharray' values='0 20; 10 0; 0 20' keyTimes='0; 0.5; 1' dur='1.5s' repeatCount='indefinite'/%3E%3Canimate attributeName='opacity' values='0; 1; 0' dur='1.5s' repeatCount='indefinite'/%3E%3C/path%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 10px;
    margin-top: -3px;
}

/* 三-六级标题递减，保持霓虹配色 */
#wenyan h3 {
    display: block;
    font-size: 1.22em;
    color: #ffeb3b; /* 黄色霓虹 */
    border-left: 4px solid #ffeb3b;
    padding-left: 10px;
}
#wenyan h4 {
    display: block;
    font-size: 1.12em;
    color: #ff4081; /* 粉色霓虹 */
}
#wenyan h4::before {
    content: "✦ "; /* 文本星星点缀 */
    color: #ff4081;
    font-size: 0.9em;
}
#wenyan h5 {
    display: block;
    font-size: 1.07em;
    color: #00e5ff; /* 蓝色霓虹 */
    border-bottom: 1px dashed #00e5ff;
    padding-bottom: 4px;
}
#wenyan h6 {
    display: block;
    font-size: 1.02em;
    color: #fff;
    opacity: 0.8;
}

/* ================= 列表系列 ================= */

#wenyan ul,
#wenyan ol {
    padding-left: 1em;
    color: #e0e6ed;
}

#wenyan li {
    margin-bottom: 0.6em;
    line-height: 1.7;
}

/* 无序列表：取消默认原点，使用 SVG 霓虹小星星图标 */
#wenyan ul {
    list-style: none;
    padding-left: 0;
}
#wenyan ul li {
    position: relative;
    padding-left: 28px;
}
#wenyan ul li::before {
    content: url("data:image/svg+xml,%3Csvg width='18' height='18' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 2l2.4 7.2h7.6l-6 4.8 2.4 7.2-6-4.8-6 4.8 2.4-7.2-6-4.8h7.6z' fill='%23FFEB3B' opacity='0.8'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    position: absolute; /* 这里使用 absolute 是为了在 li 内对齐，不违反标题规范 */
    left: 0;
    top: 5px;
    counter-increment: none; /* 明确不参与 ol 的 counter */
}

/* 有序列表：霓虹粉圆圈计数 */
#wenyan ol {
    list-style: none;
    counter-reset: custom-counter;
    padding-left: 0;
}
#wenyan ol li {
    position: relative;
    padding-left: 32px;
}
/* 只对直接子 li 计数 */
#wenyan ol > li::before {
    counter-increment: custom-counter;
    content: counter(custom-counter);
    position: absolute;
    left: 0;
    top: 3px;
    width: 22px;
    height: 22px;
    background-color: #ff4081;
    color: #fff;
    font-size: 12px;
    font-weight: bold;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 5px rgba(255, 64, 129, 0.5);
}

/* ================= 图像与表格 ================= */

/* 图片 */
#wenyan img {
    max-width: 100%;
    height: auto;
    margin: 1.5em auto;
    display: block;
    border-radius: 8px; 
    border: 2px solid #00e5ff;
    box-shadow: 0 0 15px rgba(0, 229, 255, 0.4);
}

/* 表格 */
#wenyan table {
    border-collapse: collapse;
    margin: 1.5em auto;
    width: 100%;
    max-width: 100%;
    table-layout: fixed;
    text-align: left;
    overflow: auto;
    display: table;
    word-wrap: break-word;
    word-break: break-all;
    border-radius: 8px;
    overflow: hidden; /* 保证圆角生效 */
    box-shadow: 0 0 10px rgba(255, 255, 255, 0.1);
}

#wenyan table td,
#wenyan table th {
    font-size: 0.9em;
    padding: 12px 16px;
    line-height: 1.6;
    color: #e0e6ed;
    border: 1px solid rgba(255, 255, 255, 0.2);
}

#wenyan table th {
    font-weight: bold;
    background-color: rgba(0, 229, 255, 0.1); /* 深蓝色霓虹表头 */
    color: #fff;
}

/* 斑马纹 */
#wenyan table tr:nth-child(2n) {
    background-color: rgba(255, 255, 255, 0.03);
}

/* ================= 引用与代码 ================= */

/* 引用块 */
#wenyan blockquote {
    background-color: rgba(255, 64, 129, 0.05); /* 深粉色背景 */
    border-left: 6px solid #ff4081;
    margin: 1.5em 0;
    padding: 1.2em 1.5em;
    font-size: 0.95em;
    color: #ccc;
    border-radius: 0 12px 12px 0;
}

#wenyan blockquote p {
    margin: 0;
}

/* 行内代码 */
#wenyan p code, #wenyan li code {
    color: #ffeb3b; /* 黄色代码文字 */
    background-color: rgba(255, 235, 59, 0.1);
    padding: 3px 6px;
    font-size: 0.88em;
    border-radius: 4px;
    margin: 0 2px;
}

/* 代码块外围 */
#wenyan pre {
    border-radius: 8px;
    line-height: 1.6;
    margin: 1.5em 0;
    padding: 1.2em;
    background-color: #1a1e2a; /* 深灰蓝色代码背景 */
    border: 1px solid rgba(255, 255, 255, 0.1);
}

/* 代码块：严格保持与 pre 背景色相同 */
#wenyan pre code {
    display: block;
    overflow-x: auto;
    margin: 0;
    padding: 0;
    color: #81d4fa; /* 蓝色代码文字 */
    background-color: #1a1e2a; /* 与 pre 完全一致 */
}

/* ================= 辅助元素 ================= */

/* 分割线：点状线 + 居中爆炸小花 SVG */
#wenyan hr {
    border: none;
    border-top: 2px dotted rgba(255, 255, 255, 0.3);
    margin: 3em 0;
    position: relative;
    text-align: center; /* 必须 center 才能让 after 居中 */
}

#wenyan hr::after {
    /* 正确模式：content: url() + display: block + text-align: center */
    /* SVG：多彩爆炸粒子 */
    content: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='12' cy='12' r='2' fill='%23FFEB3B'/%3E%3Ccircle cx='6' cy='6' r='1.5' fill='%23FF4081'/%3E%3Ccircle cx='18' cy='18' r='1.5' fill='%23FF4081'/%3E%3Ccircle cx='18' cy='6' r='1.5' fill='%2300E5FF'/%3E%3Ccircle cx='6' cy='18' r='1.5' fill='%2300E5FF'/%3E%3C/svg%3E");
    display: block;
    text-align: center;
    margin-top: -12px;
}

/* 超链接 */
#wenyan a {
    word-wrap: break-word;
    color: #81d4fa;
    text-decoration: none;
    border-bottom: 1px dashed #81d4fa;
}

/* 原始链接旁脚注上标 */
#wenyan .footnote {
    color: #ff80ab;
    font-size: 0.8em;
    vertical-align: super;
}

/* 脚注行 */
#wenyan #footnotes p {
    display: flex;
    margin: 0.5em 0;
    font-size: 0.88em;
    color: #aaa;
    background: rgba(255, 255, 255, 0.05);
