#wenyan h1,
#wenyan h2,
#wenyan h3,
#wenyan h4,
#wenyan h5,
#wenyan h6,
#wenyan p,
#wenyan pre {
    margin: 1.2em 0;
}

#wenyan p {
    letter-spacing: 0.5px;
}

#wenyan p strong {
    color: #d84315;
    font-weight: bold;
}

#wenyan p em {
    color: #ff6f00;
    font-style: italic;
}

/* ================= 标题系列 ================= */

/* 一级标题：底部居中太阳图标 */
#wenyan h1 {
    display: block;
    text-align: center;
    font-size: 1.67em;
    color: #e64a19;
    margin-top: 2em;
    margin-bottom: 1.5em;
    border-bottom: 3px solid #ffcc80;
    padding-bottom: 10px;
}

#wenyan h1::after {
    content: url("data:image/svg+xml,%3Csvg width='32' height='32' viewBox='0 0 32 32' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='16' cy='16' r='8' fill='%23FF6F00'/%3E%3Ccircle cx='16' cy='16' r='6' fill='%23FFB300'/%3E%3Cpath d='M16,2 L16,6 M16,26 L16,30 M2,16 L6,16 M26,16 L30,16 M6,6 L9,9 M23,23 L26,26 M6,26 L9,23 M23,9 L26,6' stroke='%23FF8F00' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E");
    display: block;
    margin-top: 10px;
    text-align: center;
}

/* 二级标题：左侧太阳光芒图标 */
#wenyan h2 {
    display: block;
    text-align: left;
    font-size: 1.37em;
    color: #f4511e;
    font-weight: bold;
    padding: 8px 16px;
    background: linear-gradient(to right, #fff3e0 0%, #ffe0b2 100%);
    border-radius: 8px;
    border-left: 4px solid #ff6f00;
    line-height: 1.4;
}

#wenyan h2::before {
    content: url("data:image/svg+xml,%3Csvg width='22' height='22' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='12' cy='12' r='5' fill='%23FFB300'/%3E%3Cpath d='M12,2 L12,5 M12,19 L12,22 M2,12 L5,12 M19,12 L22,12 M4.93,4.93 L7.05,7.05 M16.95,16.95 L19.07,19.07 M4.93,19.07 L7.05,16.95 M16.95,7.05 L19.07,4.93' stroke='%23FF8F00' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 8px;
    margin-top: -2px;
}

/* 三级标题：左侧云朵图标 */
#wenyan h3 {
    display: block;
    font-size: 1.22em;
    color: #ff5722;
    border-left: 4px solid #ffab91;
    padding-left: 10px;
}

#wenyan h3::before {
    content: url("data:image/svg+xml,%3Csvg width='18' height='18' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg' fill='%23FFCC80'%3E%3Cpath d='M19.5,15 C19.5,13.5 18.5,12.3 17,12 C17,9.2 14.8,7 12,7 C9.8,7 8,8.5 7.3,10.5 C5.4,10.8 4,12.5 4,14.5 C4,16.7 5.8,18.5 8,18.5 L18.5,18.5 C20.4,18.5 22,16.9 22,15 C22,13.1 20.4,11.5 18.5,11.5 L19.5,15 Z'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 6px;
    margin-top: -2px;
}

/* 四级标题：小光芒前缀 */
#wenyan h4 {
    display: block;
    font-size: 1.12em;
    color: #ff7043;
}

#wenyan h4::before {
    content: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M8,2 L8,4 M8,12 L8,14 M2,8 L4,8 M12,8 L14,8 M3.5,3.5 L5,5 M11,11 L12.5,12.5 M3.5,12.5 L5,11 M11,5 L12.5,3.5' stroke='%23FFB74D' stroke-width='1.5' stroke-linecap='round'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 6px;
    margin-top: -2px;
}

#wenyan h5 {
    display: block;
    font-size: 1.07em;
    color: #ff8a65;
    border-bottom: 1px dashed #ffccbc;
    padding-bottom: 4px;
}

#wenyan h6 {
    display: block;
    font-size: 1.02em;
    color: #ffab91;
}

/* ================= 列表系列 ================= */

#wenyan ul,
#wenyan ol {
    padding-left: 1em;
    color: #4a2c2a;
}

#wenyan li {
    margin-bottom: 0.6em;
    line-height: 1.7;
}

/* 无序列表：小太阳图标 */
#wenyan ul {
    list-style: none;
    padding-left: 0;
}

#wenyan ul li {
    padding-left: 28px;
    position: relative;
}

#wenyan ul li::before {
    content: url("data:image/svg+xml,%3Csvg width='14' height='14' viewBox='0 0 14 14' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='7' cy='7' r='3' fill='%23FFB300'/%3E%3Cpath d='M7,1 L7,2.5 M7,11.5 L7,13 M1,7 L2.5,7 M11.5,7 L13,7 M2.5,2.5 L3.5,3.5 M10.5,10.5 L11.5,11.5 M2.5,11.5 L3.5,10.5 M10.5,3.5 L11.5,2.5' stroke='%23FF8F00' stroke-width='1' stroke-linecap='round'/%3E%3C/svg%3E");
    position: absolute;
    left: 0;
    top: 6px;
    display: inline-block;
    counter-increment: none;
}

/* 有序列表：橙色渐变圆圈 */
#wenyan ol {
    list-style: none;
    counter-reset: custom-counter;
    padding-left: 0;
}

#wenyan ol li {
    position: relative;
    padding-left: 32px;
}

#wenyan ol > li::before {
    counter-increment: custom-counter;
    content: counter(custom-counter);
    position: absolute;
    left: 0;
    top: 3px;
    width: 22px;
    height: 22px;
    background: linear-gradient(135deg, #ff6f00 0%, #ffb300 100%);
    color: #fff;
    font-size: 12px;
    font-weight: bold;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 2px 2px 6px rgba(255, 111, 0, 0.3);
}

/* ================= 图像与表格 ================= */

#wenyan img {
    max-width: 100%;
    height: auto;
    margin: 1.5em auto;
    display: block;
    border-radius: 12px;
    box-shadow: 0 6px 16px rgba(255, 138, 101, 0.2);
    border: 2px solid #ffe0b2;
}

#wenyan table {
    border-collapse: collapse;
    margin: 1.5em auto;
    width: 100%;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 4px 12px rgba(255, 111, 0, 0.1);
}

#wenyan table td,
#wenyan table th {
    font-size: 0.9em;
    padding: 12px 16px;
    line-height: 1.6;
    color: #4a2c2a;
    border: 1px solid #ffccbc;
}

#wenyan table th {
    font-weight: bold;
    background: linear-gradient(to bottom, #ffe0b2 0%, #ffcc80 100%);
    color: #e64a19;
}

#wenyan table tr:nth-child(2n) {
    background-color: #fff8f0;
}

/* ================= 引用与代码 ================= */

/* 引用块：右下角太阳水印 */
#wenyan blockquote {
    background: linear-gradient(to right, #fff8f0 0%, #fff3e0 100%);
    border-left: 6px solid #ff8a65;
    margin: 1.5em 0;
    padding: 1.2em 1.5em;
    font-size: 0.95em;
    color: #5d4037;
    border-radius: 0 12px 12px 0;
    position: relative;

    /* 右下角太阳水印（导出时会被移除） */
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg' opacity='0.1'%3E%3Ccircle cx='40' cy='40' r='20' fill='%23FF6F00'/%3E%3Cpath d='M40,5 L40,15 M40,65 L40,75 M5,40 L15,40 M65,40 L75,40 M12,12 L20,20 M60,60 L68,68 M12,68 L20,60 M60,20 L68,12' stroke='%23FF8F00' stroke-width='3' stroke-linecap='round'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right -10px bottom -10px;
    background-size: 100px;
}

#wenyan blockquote p {
    margin: 0;
}

/* 行内代码 */
#wenyan p code,
#wenyan li code {
    color: #e64a19;
    background-color: #fff3e0;
    padding: 3px 6px;
    font-size: 0.88em;
    border-radius: 4px;
    margin: 0 2px;
}

/* 代码块 */
#wenyan pre {
    border-radius: 8px;
    line-height: 1.6;
    margin: 1.5em 0;
    padding: 1.2em;
    background-color: #fff8f0;
    border: 1px solid #ffe0b2;
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.03);
}

#wenyan pre code {
    display: block;
    overflow-x: auto;
    margin: 0;
    padding: 0;
    color: #bf360c;
    background-color: #fff8f0;
}

/* ================= 辅助元素 ================= */

/* 分割线：居中旭日图标 */
#wenyan hr {
    border: none;
    border-top: 2px dashed #ffcc80;
    margin: 3.5em 0;
    position: relative;
    text-align: center;
}

#wenyan hr::after {
    content: url("data:image/svg+xml,%3Csvg width='28' height='28' viewBox='0 0 28 28' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='14' cy='14' r='6' fill='%23FF6F00'/%3E%3Ccircle cx='14' cy='14' r='4' fill='%23FFB300'/%3E%3Cpath d='M14,2 L14,6 M14,22 L14,26 M2,14 L6,14 M22,14 L26,14 M5,5 L8,8 M20,20 L23,23 M5,23 L8,20 M20,8 L23,5' stroke='%23FF8F00' stroke-width='2' stroke-linecap='round'/%3E%3Ccircle cx='14' cy='14' r='10' stroke='%23FFCC80' stroke-width='1' fill='none' opacity='0.5'/%3E%3C/svg%3E");
    position: absolute;
    top: -14px;
    left: 50%;
    transform: translateX(-50%);
    display: inline-block;
}

/* 链接 */
#wenyan a {
    word-wrap: break-word;
    color: #f4511e;
    text-decoration: none;
    border-bottom: 1px dashed #ff8a65;
    transition: all 0.3s ease;
}

#wenyan a:hover {
    color: #d84315;
    border-bottom: 1px solid #d84315;
}

/* 脚注 */
#wenyan .footnote {
    color: #ff6f00;
    font-size: 0.8em;
    vertical-align: super;
}

#wenyan #footnotes p {
    display: flex;
    margin: 0.5em 0;
    font-size: 0.88em;
    color: #6d4c41;
    background: #fffaf5;
    padding: 10px;
    border-radius: 6px;
    border-left: 3px solid #ffab91;
}

#wenyan .footnote-num {
    display: inline;
    width: 8%;
    color: #f4511e;
    font-weight: bold;
}

#wenyan .footnote-txt {
    display: inline;
    width: 92%;
    word-wrap: break-word;
    word-break: break-all;
}

ugreen:
/**
 * 主题名称：绿联杂志 (UGREEN Magazine)
 * 风格描述：深色编号标题 + 绿色强调 + 杂志排版
 * Markdown映射:
 *   # 01 STORAGE STRATEGY → 大号灰色编号 + 绿色英文副标题（h1+h2紧邻）
 *   ## 中文标题 → 深色加粗中文标题（h3渲染）
 *   ### 四级标题 → 普通四级标题（h4渲染）
 *   > 引用 → 绿色左边框提示框
 *   > **标题** 开头 → 深色卡片
 */

/* 全局属性 */
#wenyan {
    line-height: 2;
    font-size: 16px;
    color: #30352f;
    background-color: #ffffff;
    padding: 0;
    box-sizing: border-box;
}

/* 全局子元素属性 */
#wenyan h1, #wenyan h2, #wenyan h3, #wenyan h4, #wenyan h5, #wenyan h6,
#wenyan p, #wenyan pre { margin: 0.8em 0; }

/* 段落 */
#wenyan p { letter-spacing: 0.5px; }

/* 加粗 - 绿色强调 */
#wenyan p strong { color: #12803a; font-weight: bold; }

/* 斜体 */
#wenyan p em { color: #2f3931; font-style: italic; }

/* ===== 一级标题 - 大号灰色编号 (01 02 03...) ===== */
/* 用法: # 01 STORAGE STRATEGY */
#wenyan h1 {
    font-size: 3.25em;
    color: #d7ddd6;
    font-weight: 400;
    letter-spacing: -3px;
    margin-top: 1.8em;
    margin-bottom: 0;
    line-height: 1;
    text-align: left;
}

/* ===== 二级标题 - 绿色英文副标题 ===== */
/* 用法: 紧跟在h1后面，如 ## STORAGE STRATEGY */
#wenyan h2 {
    font-size: 1em;
    color: #12803a;
    font-weight: 700;
    letter-spacing: 2px;
    margin-top: 0.4em;
    margin-bottom: 0.5em;
    line-height: 1.4;
    text-align: left;
    text-transform: uppercase;
    padding: 0;
    border: none;
    background: none;
}

/* ===== 三级标题 - 深色加粗中文标题 ===== */
/* 用法: ### 文件同步不组RAID，改用存储池间备份 */
#wenyan h3 {
    font-size: 1.5625em;
    color: #151815;
    font-weight: 800;
    margin-top: 0.2em;
    margin-bottom: 1em;
    line-height: 1.45;
    text-align: left;
    border: none;
    padding: 0;
}

/* 四级标题 */
#wenyan h4 {
    font-size: 1.15em;
    color: #2f3931;
    font-weight: 700;
}

/* 五级标题 */
#wenyan h5 {
    font-size: 1.05em;
    color: #443a31;
    font-weight: 600;
}

/* 六级标题 */
#wenyan h6 {
    font-size: 0.95em;
    color: #576B95;
    font-weight: 600;
}

/* 引用块 - 绿色左边框（提示/说明/注意） */
#wenyan blockquote {
    background: #eef4ee;
    border-left: 3px solid #1fd45f;
    margin: 1.2em 0;
    padding: 16px 18px;
    color: #526055;
    font-size: 0.875em;
    line-height: 1.85;
    border-radius: 0;
    font-style: normal;
}

/* 引用块内加粗 - 深色标题 */
#wenyan blockquote strong { color: #243026; }

/* 行内代码 */
#wenyan p code, #wenyan li code {
    color: #12803a;
    background-color: #eef4ee;
    padding: 2px 6px;
    font-size: 1em;
    border-radius: 3px;
}

/* 代码块 - 深色背景 */
#wenyan pre {
    border-radius: 8px;
    line-height: 1.6;
    margin: 1.2em 0;
    padding: 16px;
    background-color: #151a16;
    border: 1px solid #2a332c;
    color: #eef2ed;
    font-size: 0.875em;
}

#wenyan pre code {
    display: block;
    overflow-x: auto;
    color: #eef2ed;
    background-color: #151a16;
    font-size: 1em;
}

/* 链接 */
#wenyan a {
    color: #12803a;
    text-decoration: none;
    border-bottom: 1px solid rgba(26, 181, 82, 0.3);
}

/* 列表 */
#wenyan ul, #wenyan ol { padding-left: 1.2em; color: #30352f; }
#wenyan li { margin-bottom: 0.5em; line-height: 1.8; }
#wenyan li::marker { color: #12803a; }

/* 表格 */
#wenyan table { border-collapse: collapse; margin: 1.2em auto; width: 100%; }
#wenyan table td, #wenyan table th { font-size: 0.9em; padding: 10px 14px; border: 1px solid #cfd6cf; color: #30352f; }
#wenyan table th { font-weight: 600; background-color: #151a16; color: #89f0a8; }
#wenyan table tr:nth-child(2n) { background-color: #f0f4f0; }

/* 图片 */
#wenyan img { max-width: 100%; height: auto; margin: 1.5em auto; display: block; border-radius: 8px; }

/* 分割线 */
#wenyan hr { border: none; border-top: 1px solid #cfd6cf; margin: 2em 0; }

/* 脚注 */
#wenyan .footnote { font-size: 0.8em; color: #657067; }

winter:
/**
