    background-color: #eaf2f8; 
    border-radius: 8px;
    border-left: 4px solid #3498db; 
}

#wenyan h2::before {
    /* 纯手绘：带有分支的精细六角大雪花 */
    content: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cg stroke='%233498db' stroke-width='1.5' stroke-linecap='round'%3E%3Cline x1='12' y1='2' x2='12' y2='22'/%3E%3Cline x1='3.34' y1='7' x2='20.66' y2='17'/%3E%3Cline x1='3.34' y1='17' x2='20.66' y2='7'/%3E%3Cpath d='M12 6l-2-2m2 2l2-2M6 9l-2 0m2 0l0-2M18 9l2 0m-2 0l0-2M12 18l-2 2m2-2l2 2M6 15l-2 0m2 0l0 2M18 15l2 0m-2 0l0 2' fill='none'/%3E%3C/g%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 8px;
    margin-top: -3px;
}

/* 三级标题：左侧【基础六芒星雪花】SVG */
#wenyan h3 {
    display: block;
    font-size: 1.22em;
    color: #2471a3;
    border-bottom: 1px solid #aed6f1;
    padding-bottom: 6px;
}
#wenyan h3::before {
    content: url("data:image/svg+xml,%3Csvg width='18' height='18' viewBox='0 0 18 18' xmlns='http://www.w3.org/2000/svg' stroke='%235dade2' stroke-width='1.5' stroke-linecap='round'%3E%3Cline x1='9' y1='2' x2='9' y2='16'/%3E%3Cline x1='3' y1='5' x2='15' y2='13'/%3E%3Cline x1='3' y1='13' x2='15' y2='5'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 6px;
    margin-top: -2px;
}

/* 四级标题：左侧【小巧米字雪花】SVG */
#wenyan h4 {
    display: block;
    font-size: 1.12em;
    color: #2980b9;
}
#wenyan h4::before {
    content: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' xmlns='http://www.w3.org/2000/svg'%3E%3Cg stroke='%2385C1E9' stroke-width='1.5' stroke-linecap='round'%3E%3Cline x1='8' y1='2' x2='8' y2='14'/%3E%3Cline x1='3' y1='5' x2='13' y2='11'/%3E%3Cline x1='3' y1='11' x2='13' y2='5'/%3E%3C/g%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 6px;
    margin-top: -2px;
}

#wenyan h5 {
    display: block;
    font-size: 1.07em;
    color: #3498db;
    border-bottom: 1px dashed #d6eaf8;
    padding-bottom: 4px;
}

#wenyan h6 {
    display: block;
    font-size: 1.02em;
    color: #5dade2;
}

/* ================= 列表系列 ================= */
#wenyan ul,
#wenyan ol {
    padding-left: 1em;
    color: #2c3e50;
}

#wenyan li {
    margin-bottom: 0.6em;
    line-height: 1.7;
}

/* 无序列表：使用【八芒星冰晶】SVG */
#wenyan ul {
    list-style: none;
    padding-left: 0;
}
#wenyan ul li {
    padding-left: 4px;
}
#wenyan ul li::before {
    content: url("data:image/svg+xml,%3Csvg width='14' height='14' viewBox='0 0 14 14' xmlns='http://www.w3.org/2000/svg' stroke='%233498db' stroke-width='1.2' stroke-linecap='round'%3E%3Cline x1='7' y1='1' x2='7' y2='13'/%3E%3Cline x1='1' y1='7' x2='13' y2='7'/%3E%3Cline x1='3' y1='3' x2='11' y2='11'/%3E%3Cline x1='3' y1='11' x2='11' y2='3'/%3E%3C/svg%3E");
    display: inline-block;
    vertical-align: middle;
    margin-right: 8px;
    margin-left: 4px; 
    counter-increment: none; 
}

/* 有序列表：冰蓝底色圆圈 */
#wenyan ol {
    list-style: none;
    counter-reset: custom-counter;
    padding-left: 0;
}
#wenyan ol li {
    position: relative;
    padding-left: 32px;
}
#wenyan ol > li::before {
    counter-increment: custom-counter;
    content: counter(custom-counter);
    position: absolute;
    left: 0;
    top: 4px;
    width: 20px;
    height: 20px;
    background-color: #217cb9;
    color: #fff;
    font-size: 12px;
    border-radius: 4px; 
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 1px 2px 4px rgba(93, 173, 226, 0.3);
}

/* ================= 图像与表格 ================= */
#wenyan img {
    max-width: 100%;
    height: auto;
    margin: 1.5em auto;
    display: block;
    border-radius: 8px; 
    box-shadow: 0 4px 12px rgba(41, 128, 185, 0.1);
    border: 1px solid #eaf2f8;
}

#wenyan table {
    border-collapse: collapse;
    margin: 1.5em auto;
    width: 100%;
    max-width: 100%;
    table-layout: fixed;
    text-align: left;
    display: table;
    word-wrap: break-word;
    word-break: break-all;
    border-radius: 8px;
    overflow: hidden; 
    box-shadow: 0 2px 8px rgba(52, 152, 219, 0.08);
}

#wenyan table td,
#wenyan table th {
    font-size: 0.9em;
    padding: 12px 16px;
    line-height: 1.6;
    color: #2c3e50;
    border: 1px solid #d6eaf8;
}

#wenyan table th {
    font-weight: bold;
    background-color: #eaf2f8; 
    color: #154360;
}

#wenyan table tr:nth-child(2n) {
    background-color: #f7fbff; 
}

/* ================= 引用与代码 ================= */

/* 引用块：右下角增加【巨型半透明雪花】SVG 满铺水印 */
#wenyan blockquote {
    background-color: #f0f6fa; 
    border-left: 6px solid #5dade2;
    margin: 1.5em 0;
    padding: 1.2em 1.5em;
    font-size: 0.95em;
    color: #34495e;
    border-radius: 0 12px 12px 0;
    position: relative;
    /* 右下角超大分支雪花水印 */
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg' fill='none' stroke='%23AED6F1' opacity='0.25'%3E%3Cg stroke-width='2' stroke-linecap='round'%3E%3Cline x1='50' y1='10' x2='50' y2='90'/%3E%3Cline x1='15.35' y1='30' x2='84.65' y2='70'/%3E%3Cline x1='15.35' y1='70' x2='84.65' y2='30'/%3E%3Cpath d='M50 25l-10-10m10 10l10-10M25 35l-14 0m14 0l0-14M75 35l14 0m-14 0l0-14M50 75l-10 10m10-10l10 10M25 65l-14 0m14 0l0 14M75 65l14 0m-14 0l0 14'/%3E%3C/g%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right -20px bottom -20px;
    background-size: 100px;
}

#wenyan blockquote p {
    margin: 0;
}

/* 行内代码 */
#wenyan p code, #wenyan li code {
    color: #154360;
    background-color: #eaf2f8;
    padding: 3px 6px;
    font-size: 0.88em;
    border-radius: 4px;
    margin: 0 2px;
}

/* 代码块外围 */
#wenyan pre {
    border-radius: 8px;
    line-height: 1.6;
    margin: 1.5em 0;
    padding: 1.2em;
    background-color: #f2f7fa; 
    border: 1px solid #d6eaf8; 
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.03);
}

#wenyan pre code {
    display: block;
    overflow-x: auto;
    margin: 0;
    padding: 0;
    color: #1a5276; 
    background-color: #f2f7fa; 
}

/* ================= 辅助元素 ================= */

/* 分割线：居中【戴红围脖和黑帽子的完整雪人】SVG */
#wenyan hr {
    border: none;
    border-top: 2px dashed #aed6f1;
    margin: 4em 0; /* 加大边距给雪人留空间 */
    text-align: center;
}

#wenyan hr::after {
    /* 纯手绘超清小雪人：底层加粗实心白底遮挡虚线 -> 身体 -> 眼睛/纽扣 -> 橘色胡萝卜鼻子 -> 红色围脖 -> 黑色礼帽 */
    content: url("data:image/svg+xml,%3Csvg width='46' height='46' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='20' cy='20' r='18' fill='%23F8FBFC'/%3E%3Ccircle cx='20' cy='26' r='10' fill='%23ffffff' stroke='%2385C1E9' stroke-width='1.5'/%3E%3Ccircle cx='20' cy='14' r='7' fill='%23ffffff' stroke='%2385C1E9' stroke-width='1.5'/%3E%3Ccircle cx='17.5' cy='12.5' r='1' fill='%232c3e50'/%3E%3Ccircle cx='22.5' cy='12.5' r='1' fill='%232c3e50'/%3E%3Cpolygon points='20,14 26,16 20,16' fill='%23e67e22'/%3E%3Ccircle cx='20' cy='21' r='1' fill='%232c3e50'/%3E%3Ccircle cx='20' cy='25' r='1' fill='%232c3e50'/%3E%3Ccircle cx='20' cy='29' r='1' fill='%232c3e50'/%3E%3Cpath d='M14 18 Q20 22 26 18' stroke='%23e74c3c' stroke-width='2.5' stroke-linecap='round' fill='none'/%3E%3Cpath d='M24 18 L22 24' stroke='%23e74c3c' stroke-width='2.5' stroke-linecap='round'/%3E%3Crect x='15' y='7' width='10' height='1.5' fill='%232c3e50'/%3E%3Crect x='16.5' y='1' width='7' height='6' fill='%232c3e50'/%3E%3C/svg%3E");
    display: block;
    text-align: center;
    margin-top: -23px; /* 让雪人骑在虚线上 */
}

/* 链接 */
#wenyan a {
    word-wrap: break-word;
    color: #2980b9;
    text-decoration: none;
    border-bottom: 1px dashed #85c1e9;
    transition: all 0.3s ease;
}

#wenyan a:hover {
    color: #154360;
    border-bottom: 1px solid #154360;
}

/* 脚注 */
#wenyan .footnote {
    color: #3498db;
    font-size: 0.8em;
    vertical-align: super;
}

#wenyan #footnotes p {
    display: flex;
    margin: 0.5em 0;
    font-size: 0.88em;
    color: #5d6d7e;
    background: #fdfefe;
    padding: 8px;
    border-radius: 6px;
    border: 1px solid #eaf2f8;
}

#wenyan .footnote-num {
    display: inline;
    width: 8%;
    color: #2980b9;
    font-weight: bold;
}

#wenyan .footnote-txt {
    display: inline;
    width: 92%;
    word-wrap: break-word;
    word-break: break-all;
}
